function sincronizarPreLancamentos(){if(typeof db==='undefined')return false;if(!Array.isArray(db.preLancamentos))db.preLancamentos=[];if(!prePronto())return false;var mudouLista=deduplicarPre(),atuais={},porOrigem={},custosPorOrigem={};db.preLancamentos.forEach(function(x){if(x&&x.origemChave)porOrigem[x.origemChave]=x});arr('custos').forEach(function(x){if(x&&x.origemChave)custosPorOrigem[x.origemChave]=true});candidatosPreLancamento().forEach(function(novo){if(!moduloPronto(novo.origemModulo))return;atuais[novo.origemChave]=true;var existente=porOrigem[novo.origemChave];if(!existente){if(!custosPorOrigem[novo.origemChave]){db.preLancamentos.push(novo);porOrigem[novo.origemChave]=novo;mudouLista=true}return}if(existente.situacaoPre==='descartado'||existente.situacaoPre==='confirmado'||existente.editadoManualmente)return;var mudou=false;['data','competencia','veiculo','motorista','categoria','tipo','descricao','valor','parcelas','origemNome','origemRegistroId'].forEach(function(k){if(existente[k]!==novo[k]){existente[k]=novo[k];mudou=true}});if(mudou){existente.atualizadoEm=novo.atualizadoEm;mudouLista=true}});var tamanhoAntes=db.preLancamentos.length;db.preLancamentos=db.preLancamentos.filter(function(x){if(x.situacaoPre==='confirmado'||x.situacaoPre==='descartado')return true;if(!moduloPronto(x.origemModulo))return true;return !!atuais[x.origemChave]});return mudouLista||tamanhoAntes!==db.preLancamentos.length}
function implementoMeses(x){return Math.max(0,Math.min(600,Math.floor(num(x&&x.meses))))}
function implementoMensal(x){var base=num(x&&x.valor)-num(x&&x.residual),meses=implementoMeses(x);return base>0&&meses>0?base/meses:0}
