function confirmarTransferencia(xid){var lista=arr('implementos'),x=lista.find(function(y){return y.id===xid});if(!x)return;var hist=implementoVinculos(x),atual=hist.length?hist[hist.length-1]:null;if(!atual)return;var sel=document.getElementById('cusImpTransfVeiculo'),mesEl=document.getElementById('cusImpTransfMes');var destino=sel?String(sel.value||'').trim():'',mes=mesEl?String(mesEl.value||'').trim():'';if(!destino){alert('Selecione o veículo de destino.');return}if(normalizarPlaca(destino)===normalizarPlaca(atual.veiculo)){alert('O implemento já está vinculado a este veículo.');return}if(veiculoVendido(destino)){alert('Este veículo está marcado como vendido e não pode receber o implemento.');return}if(!/^\d{4}-\d{2}$/.test(mes)){alert('Informe a competência no formato AAAA-MM.');return}if(mes<=atual.inicio){alert('A competência da transferência deve ser posterior a '+atual.inicio+'.');return}var fim=implementoFim(x);if(fim&&mes>fim){alert('A vida útil deste implemento termina em '+fim+'. Escolha uma competência dentro do prazo.');return}hist.push({veiculo:destino,inicio:mes});x.vinculos=hist;x.veiculo=destino;var ix=lista.findIndex(function(y){return y.id===x.id});if(ix>=0)db.implementos[ix]=x;if(typeof salvarNuvem==='function')salvarNuvem(['implementos']);fecharTransferencia();render()}
