function numeroSolto(v){var s=String(v==null?'':v).trim().replace(/[^\d,.-]/g,'');if(!s)return 0;if(s.indexOf(',')!==-1)s=s.replace(/\./g,'').replace(',','.');var m=s.match(/-?\d+(\.\d+)?/);return m?Number(m[0])||0:0}
function freteKm(f){return Math.max(0,numeroSolto(f.fredistancia))}
function fretePesoTon(f){var t=String(f.frepeso||'').toUpperCase(),n=numeroSolto(f.frepeso);if(!n)return 0;if(t.indexOf('KG')!==-1||n>=1000)return n/1000;return n}
function freteVolume(f){return Math.max(0,numeroSolto(f.frevolume))}
function freteReceita(f){return num(f.frevalor)}
function fretePagoTerceiro(f){return num(f.frecustoterceiro)}
function chaveLocal(v){return String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase().replace(/[^A-Z0-9]/g,'')}
function freteRota(f){var o=String(f.freorigem||'--'),d=String(f.fredestino||'--');return o+' → '+d}
function tipoVeiculoNormalizado(v){var s=String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase().replace(/[^A-Z0-9]/g,'');if(!s)return '';if(s.indexOf('RODOTREM')!==-1)return 'Rodotrem';if(s.indexOf('BITREM')!==-1)return 'Bitrem';if(s.indexOf('CARRETA')!==-1||s.indexOf('CAVALOMECANICO')!==-1)return 'Carreta';if(s.indexOf('TRUCK')!==-1||s.indexOf('TRUCADO')!==-1)return 'Truck';if(s.indexOf('TOCO')!==-1)return 'Toco';if(s.indexOf('34')!==-1||s.indexOf('TRESQUARTOS')!==-1)return '3/4';if(s.indexOf('VUC')!==-1)return 'VUC';return String(v||'').trim()}
function veiculoCadastro(placa){var p=normalizarPlaca(placa);return arr('veiculos').find(function(v){return normalizarPlaca(v.vplaca)===p})||null}
function terceiroDoFrete(f){var r=String(f.freterceiro||'').toUpperCase(),p=normalizarPlaca(f.freterceiro);return arr('terceiros').find(function(t){var pl=normalizarPlaca(t.terplaca);return (pl&&p.indexOf(pl)!==-1)||(r&&[t.terempresa,t.ternome,t.terproprietario].some(function(n){return n&&r.indexOf(String(n).toUpperCase())!==-1}))})||null}
function tipoFrete(f){if(f.freexecucao==='terceiro'){var t=terceiroDoFrete(f);return tipoVeiculoNormalizado((t&&t.tertipoveiculo)||f.fretipoveiculo)}var v=veiculoCadastro(f.freveiculo);return tipoVeiculoNormalizado(v&&v.vtipo||f.fretipoveiculo)}
function capacidadeVeiculo(v){var kg=Math.max(0,numeroSolto(v.vpliquido)),m3=Math.max(0,numeroSolto(v.vm3));return {ton:kg/1000,m3:m3}}
function tiposCompativeis(ton,m3){var tipos={};arr('veiculos').filter(function(v){return !veiculoVendido(v.vplaca)}).forEach(function(v){var tipo=tipoVeiculoNormalizado(v.vtipo),cap=capacidadeVeiculo(v);if(!tipo||(!cap.ton&&!cap.m3))return;if((!ton||cap.ton>=ton)&&(!m3||cap.m3>=m3)){var medida=(ton?cap.ton/ton:0)+(m3?cap.m3/m3:0);if(!tipos[tipo]||medida<tipos[tipo].medida)tipos[tipo]={tipo:tipo,medida:medida,ton:cap.ton,m3:cap.m3}}});return Object.keys(tipos).map(function(k){return tipos[k]}).sort(function(a,b){return a.medida-b.medida})}
function conferenciaVeiculo(placa,f,base){var itens=filtrados(placa,f,base),cat={};itens.forEach(function(x){cat[x.categoria]=(cat[x.categoria]||0)+num(x.valor)});var km=kmPeriodo(placa,f.ini,f.fim),dep=0;try{if(window.FMResultadoAPI)dep=window.FMResultadoAPI.resumo(placa,f,'competencia',base).c.depreciacao||0}catch(e){}var pend=prePendentes().filter(function(x){var c=x.competencia||mesChave(x.data);return normalizarPlaca(x.veiculo)===normalizarPlaca(placa)&&c>=mesChave(f.ini)&&c<=mesChave(f.fim)}).length;var bloqueios=[],alertas=[];if(!km)bloqueios.push('sem KM fechado');if(!cat['Combustível'])bloqueios.push('sem combustível');if(!cat['Salário'])bloqueios.push('sem folha do motorista');if(pend)bloqueios.push(pend+' pré-lançamento(s) pendente(s)');if(!cat['Seguro'])alertas.push('sem seguro');if(!dep)alertas.push('sem depreciação FIPE');if(!cat['IPVA / Licenciamento'])alertas.push('sem IPVA/licenciamento');if(!cat['Manutenção preventiva']&&!cat['Manutenção corretiva']&&!cat['Plano de Manutenção']&&!cat['Peças'])alertas.push('sem manutenção no período');return {placa:placa,km:km,completo:!bloqueios.length,bloqueios:bloqueios,alertas:alertas}}
function custoKmVeiculo(placa,f,base){if(!conferenciaVeiculo(placa,f,base).completo)return 0;if(window.FMResultadoAPI){try{var r=window.FMResultadoAPI.resumo(placa,f,'competencia',base);return r.custoKm||0}catch(e){}}var itens=filtrados(placa,f,base),total=itens.reduce(function(s,x){return s+x.valor},0),km=kmPeriodo(placa,f.ini,f.fim);return km?total/km:0}
function fretesPeriodo(f){return arr('fretes').filter(function(x){var dt=data(x.fredata);if(String(x.frestatus||'')==='Cancelado')return false;if(f.ini&&dt&&dt<data(f.ini))return false;if(f.fim&&dt&&dt>data(f.fim))return false;if(f.v&&x.freexecucao!=='terceiro'&&normalizarPlaca(x.freveiculo)!==normalizarPlaca(f.v))return false;return true})}
function vazioComparativo(){return {viagens:0,km:0,ton:0,m3:0,receita:0,custo:0}}
function somarComparativo(alvo,dados){alvo.viagens++;alvo.km+=dados.km;alvo.ton+=dados.ton;alvo.m3+=dados.m3;alvo.receita+=dados.receita;alvo.custo+=dados.custo}
function comparativoTerceirizacao(){
 var f=filtros(),base=todosBase(),lista=fretesPeriodo(f),cacheKm={};
 var rotas={},pendencias=0;
 lista.forEach(function(x){
  var km=freteKm(x),ton=fretePesoTon(x),m3=freteVolume(x),receita=freteReceita(x),terc=x.freexecucao==='terceiro',tipo=tipoFrete(x),custo=0;
  if(terc){custo=fretePagoTerceiro(x);if(!custo||!km||!tipo)pendencias++}
  else{var placa=normalizarPlaca(x.freveiculo);if(placa&&cacheKm[placa]===undefined)cacheKm[placa]=custoKmVeiculo(x.freveiculo,f,base);var ck=placa&&cacheKm[placa]||0;custo=km*ck;if(!placa||!km||!ck||!tipo)pendencias++}
  var dados={km:km,ton:ton,m3:m3,receita:receita,custo:custo};
  var chave=chaveLocal(x.freorigem)+'>'+chaveLocal(x.fredestino)+'|'+(tipo||'Não informado');
  if(!rotas[chave])rotas[chave]={rota:freteRota(x),tipo:tipo||'Não informado',proprio:vazioComparativo(),terceiro:vazioComparativo(),pesoMax:0,volumeMax:0};
  rotas[chave].pesoMax=Math.max(rotas[chave].pesoMax,ton);rotas[chave].volumeMax=Math.max(rotas[chave].volumeMax,m3);
  somarComparativo(terc?rotas[chave].terceiro:rotas[chave].proprio,dados);
 });
 var proprio=vazioComparativo(),terceiro=vazioComparativo(),simuladoProprio=0,comparaveis=0;
 var grupos=Object.keys(rotas).map(function(k){var r=rotas[k],cp=divSeguro(r.proprio.custo,r.proprio.km);r.recomendado=(tiposCompativeis(r.pesoMax,r.volumeMax)[0]||{}).tipo||'';r.comparavel=!!(r.tipo!=='Não informado'&&cp&&r.terceiro.custo&&r.terceiro.km);if(r.comparavel){comparaveis++;somarGrupo(proprio,r.proprio);somarGrupo(terceiro,r.terceiro);simuladoProprio+=r.terceiro.km*cp}return r});
 var placasProprias={};lista.forEach(function(x){if(x.freexecucao!=='terceiro'&&x.freveiculo)placasProprias[normalizarPlaca(x.freveiculo)]=x.freveiculo});var conferencia=Object.keys(placasProprias).map(function(k){return conferenciaVeiculo(placasProprias[k],f,base)});
 return {conferencia:conferencia,filtros:f,proprio:proprio,terceiro:terceiro,rotas:grupos,pendencias:pendencias,simuladoProprio:simuladoProprio,total:lista.length,comparaveis:comparaveis};
}
function somarGrupo(alvo,grupo){['viagens','km','ton','m3','receita','custo'].forEach(function(k){alvo[k]+=grupo[k]||0})}
function divSeguro(a,b){return b?a/b:0}
function celulaIndice(valor,unidade){return valor?brl(valor)+unidade:'--'}
function renderTerceirizacao(){
 var wrap=document.getElementById('cusTercResumo');if(!wrap)return;
 var c=comparativoTerceirizacao(),p=c.proprio,t=c.terceiro;
 var kmP=divSeguro(p.custo,p.km),kmT=divSeguro(t.custo,t.km);
 var economia=t.custo-c.simuladoProprio;
 var veredito;
 if(!c.total)veredito='Cadastre os fretes indicando quem executou (frota própria ou terceiro) para gerar a comparação.';
 else if(!c.comparaveis)veredito='Ainda não há viagens próprias e terceirizadas da mesma rota e do mesmo tipo de veículo para uma comparação válida.';
 else if(kmP<kmT)veredito='Comparando somente a mesma rota e o mesmo tipo de veículo, a frota própria sai '+brl(kmT-kmP)+' por km mais barata.';
 else veredito='Comparando somente a mesma rota e o mesmo tipo de veículo, o terceiro sai '+brl(kmP-kmT)+' por km mais barato.';
 wrap.innerHTML=''
  +'<div class="cus-kpis">'
  +'<div class="cus-kpi"><span>Custo por km — própria</span><strong>'+celulaIndice(kmP,'')+'</strong><small>'+p.viagens+' viagem(ns) · '+Math.round(p.km).toLocaleString('pt-BR')+' km</small></div>'
  +'<div class="cus-kpi"><span>Custo por km — terceiro</span><strong>'+celulaIndice(kmT,'')+'</strong><small>'+t.viagens+' viagem(ns) · '+Math.round(t.km).toLocaleString('pt-BR')+' km</small></div>'
  +'<div class="cus-kpi"><span>Custo por tonelada</span><strong>'+celulaIndice(divSeguro(p.custo,p.ton),'')+' / '+celulaIndice(divSeguro(t.custo,t.ton),'')+'</strong><small>própria / terceiro</small></div>'
  +'<div class="cus-kpi"><span>Custo por m³</span><strong>'+celulaIndice(divSeguro(p.custo,p.m3),'')+' / '+celulaIndice(divSeguro(t.custo,t.m3),'')+'</strong><small>própria / terceiro</small></div>'
  +'</div>'
  +'<div class="cus-note" style="margin-top:10px"><b>Conclusão:</b> '+esc(veredito)+'</div>'
  +'<div class="cus-note">Foram considerados <b>'+c.comparaveis+' grupo(s) comparável(is)</b>. Pago aos terceiros nesses grupos: <b>'+brl(t.custo)+'</b>. Custo estimado com veículo próprio equivalente: <b>'+brl(c.simuladoProprio)+'</b> ('+(economia>=0?'economia':'custo adicional')+' de <b>'+brl(Math.abs(economia))+'</b>).</div>'
  +(c.conferencia.length?'<div class="cus-note" style="margin-top:10px"><b>Conferência dos dados reais por veículo próprio</b> — só entra na comparação o veículo sem bloqueios.</div><div class="cus-table-wrap"><table class="table table-sm cus-table"><thead><tr><th>Veículo</th><th>KM fechado</th><th>Situação</th><th>Bloqueios</th><th>Alertas</th></tr></thead><tbody>'+c.conferencia.map(function(v){return '<tr><td><b>'+esc(v.placa)+'</b></td><td>'+Math.round(v.km).toLocaleString('pt-BR')+'</td><td>'+(v.completo?'<span style="color:#15803d;font-weight:600">Completo</span>':'<span style="color:#b91c1c;font-weight:600">Dados incompletos</span>')+'</td><td>'+esc(v.bloqueios.join(', ')||'—')+'</td><td>'+esc(v.alertas.join(', ')||'—')+'</td></tr>'}).join('')+'</tbody></table></div>':'')
  +(c.pendencias?'<div class="cus-note" style="color:#b45309">'+c.pendencias+' frete(s) ficaram fora: sem distância, sem tipo do veículo, veículo próprio com dados incompletos ou sem valor pago ao terceiro.</div>':'');
 var tb=document.getElementById('cusTercLista');
 if(tb){
  var linhas=c.rotas.slice().sort(function(a,b){return (b.proprio.custo+b.terceiro.custo)-(a.proprio.custo+a.terceiro.custo)});
  var pg=paginar(linhas,'paginaTerceirizacao');
  tb.innerHTML=pg.itens.map(function(r){
   var cp=divSeguro(r.proprio.custo,r.proprio.km),ct=divSeguro(r.terceiro.custo,r.terceiro.km);
    var rec=(cp&&ct)?(cp<ct?'Usar frota própria':'Terceirizar'):'Sem par equivalente';
   var dif=(cp&&ct)?brl(Math.abs(cp-ct))+' por km':'--';
    var capacidade=(r.pesoMax?r.pesoMax.toLocaleString('pt-BR',{maximumFractionDigits:2})+' t':'--')+' / '+(r.volumeMax?r.volumeMax.toLocaleString('pt-BR',{maximumFractionDigits:2})+' m³':'--');
    return '<tr><td><b>'+esc(r.rota)+'</b></td><td>'+esc(r.tipo)+'</td><td>'+esc(r.recomendado||'Capacidade não cadastrada')+'<small class="d-block text-muted">'+esc(capacidade)+'</small></td><td>'+r.proprio.viagens+'</td><td>'+r.terceiro.viagens+'</td><td>'+celulaIndice(cp,'')+'</td><td>'+celulaIndice(ct,'')+'</td><td>'+esc(dif)+'</td><td>'+esc(rec)+'</td></tr>';
   }).join('')||'<tr><td colspan="9" class="cus-empty">Nenhum frete no período selecionado.</td></tr>';
  var pel=document.getElementById('cusTercPaginacao');if(pel)pel.innerHTML=pg.html;
 }
}
function trocarAba(nome){estado.tab=nome;document.querySelectorAll('.cus-tab').forEach(function(e){e.classList.toggle('active',e.dataset.tab===nome)});document.querySelectorAll('.cus-pane').forEach(function(e){e.classList.toggle('hidden',e.id!=='cusPane-'+nome)});render()}
function exportar(){var f=filtros(),base=todosBase(),l=filtrados(undefined,f,base),det=l.map(function(x){return {'Data':dBR(x.data),'Competência':dBR(x.competencia),'Veículo':x.veiculo||'Frota geral','Motorista':x.motorista||'','Categoria':x.categoria,'Tipo':x.tipo,'Descrição':x.descricao,'Parcela':x.parcelas>1?x.parcelaAtual+'/'+x.parcelas:'À vista','Valor total (R$)':x.valorTotal||x.valor,'Origem':x.origem,'Situação':x.status,'Valor mensal (R$)':x.valor}});if(!det.length){alert('Não há dados para exportar.');return}var wb=XLSX.utils.book_new(),ws=XLSX.utils.json_to_sheet(det),placas=f.v?[f.v]:veiculosGestao(),res=[];placas.forEach(function(p){var fat=faturamentoPeriodo(p,f.ini,f.fim),liq=receitaLiquidaPeriodo(p,f.ini,f.fim),km=kmPeriodo(p,f.ini,f.fim),t=0;if(window.FMResultadoAPI){var resumo=window.FMResultadoAPI.resumo(p,f,f.modo,base);t=resumo.c.total;km=resumo.km}else{t=filtrados(p,f,base).reduce(function(s,x){return s+x.valor},0)}if(t||km||fat||liq)res.push({'Veículo':p,'Faturamento total (R$)':fat,'Receita líquida (R$)':liq,'Custo total (R$)':t,'KM':km,'Custo por KM (R$)':km?t/km:0})});XLSX.utils.book_append_sheet(wb,ws,'Lançamentos');XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(res),'Resumo por veículo');XLSX.writeFile(wb,'FrotaMaster_Gestao_Frota_'+hoje()+'.xlsx')}
function veiculosGestao(){var m={},vendidos={};arr('veiculos').forEach(function(v){if(!v.vplaca)return;if(veiculoVendido(v.vplaca))vendidos[normalizarPlaca(v.vplaca)]=true;else m[v.vplaca]=true});['custos','custosRecorrentes','quilometragens','producoes','gestaoDepreciacoes'].forEach(function(k){arr(k).forEach(function(x){if(x.veiculo&&!vendidos[normalizarPlaca(x.veiculo)])m[x.veiculo]=true})});return Object.keys(m).sort()}
