 window.mudarPaginaGestao=function(chave,p){estado[chave]=p;render()};window.fmSincronizarPreLancamentos=sincronizarPreLancamentos;window.editarPreLancamento=editarPre;window.confirmarPreLancamento=confirmarPre;window.confirmarPreLancamentosSelecionados=confirmarSelecionados;window.selecionarPreLancamentos=selecionarPre;window.descartarPreLancamento=descartarPre;window.FMCustosAPI={filtrados:filtrados,filtros:filtros,kmPeriodo:kmPeriodo,todosBase:todosBase,brl:brl,num:num,veiculos:veiculosGestao};window.renderCustosFrota=render;window.filtrarCustosFrota=function(){reiniciarPaginasFiltros();render()};window.limparFiltrosCustos=limparFiltros;window.salvarCustoFrota=salvarCusto;window.editarCustoFrota=editarCusto;window.excluirCustoFrota=excluirCusto;window.alterarStatusCustoFrota=alterarStatusCusto;window.limparCustoFrota=limparCusto;window.alternarParcelamentoFrota=alternarParcelamento;window.atualizarValorCustoRecorrente=atualizarValorRec;window.salvarCustoRecorrente=salvarRec;window.editarCustoRecorrente=editarRec;window.cancelarCustoRecorrente=cancelarRec;window.salvarCustoPessoal=salvarPessoal;window.atualizarTotalFolha=atualizarTotalFolha;window.cancelarCustoPessoal=function(){['cusPesVeiculo','cusPesMotorista','cusPesSalario','cusPesEncargos','cusPesFgts','cusPesBeneficios'].forEach(function(id){var e=document.getElementById(id);if(e)e.value=''});atualizarTotalFolha()};window.excluirCustoRecorrente=excluirRec;window.salvarQuilometragem=salvarKm;window.editarQuilometragem=editarKm;window.cancelarQuilometragem=cancelarKm;window.excluirQuilometragem=excluirKm;window.atualizarOdometroInicial=atualizarOdometroInicial;window.calcularQuilometragem=calcularKm;window.aplicarPeriodoCustos=periodo;window.trocarAbaCustos=trocarAba;window.exportarCustosFrota=exportar;window.custoCategoriaChange=categoriaChange;window.salvarImplemento=salvarImplemento;window.cancelarImplemento=limparImplemento;window.editarImplementoFrota=editarImplemento;window.excluirImplementoFrota=excluirImplemento;window.transferirImplementoFrota=transferirImplemento;window.calcularDepreciacaoImplemento=calcularImplemento;
